<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';
import{parityMessages}from'./parity-labels';
import{hexToRGB,rgbToHex,rgbToHSV,hsvToRGB,validHex}from'../../../packages/comp-bridge/view-settings.mjs';
import type{Language}from'./types';
const props=defineProps<{language:Language;color:string;background:string;swatches:string[];disabled:boolean}>(),emit=defineEmits(['color','background','swatches','close']),t=computed(()=>parityMessages[props.language]),target=ref('foreground'),hue=ref(0),square=ref<HTMLCanvasElement>(),selected=ref(-1);
const active=computed(()=>target.value==='foreground'?props.color:props.background),rgb=computed(()=>hexToRGB(active.value)),hsv=computed(()=>{const result=rgbToHSV(rgb.value);if(!result[1])result[0]=hue.value;return result;}),hex=ref(active.value);
watch(active,value=>{hex.value=value;const [h,s]=rgbToHSV(hexToRGB(value));if(s)hue.value=h;},{immediate:true});
function change(value:string){if(!props.disabled&&validHex(value))emit(target.value==='foreground'?'color':'background',value);}
function component(index:number,value:number,mode:string){if(!Number.isFinite(value))return;const values=mode==='rgb'?[...rgb.value]:[...hsv.value];values[index]=Math.max(0,Math.min(mode==='rgb'?255:index?100:360,value));if(mode==='hsv'&&index===0)hue.value=values[0];change(rgbToHex(mode==='rgb'?values:hsvToRGB(values)));}
function draw(){const canvas=square.value;if(!canvas)return;const context=canvas.getContext('2d')!;context.fillStyle=rgbToHex(hsvToRGB([hue.value,100,100]));context.fillRect(0,0,200,140);let gradient=context.createLinearGradient(0,0,200,0);gradient.addColorStop(0,'#ffffff');gradient.addColorStop(1,'#ffffff00');context.fillStyle=gradient;context.fillRect(0,0,200,140);gradient=context.createLinearGradient(0,0,0,140);gradient.addColorStop(0,'#00000000');gradient.addColorStop(1,'#000000');context.fillStyle=gradient;context.fillRect(0,0,200,140);}
let dragging=false;
function pick(event:PointerEvent){if(props.disabled)return;const bounds=square.value!.getBoundingClientRect(),s=Math.max(0,Math.min(1,(event.clientX-bounds.left)/bounds.width))*100,v=(1-Math.max(0,Math.min(1,(event.clientY-bounds.top)/bounds.height)))*100;change(rgbToHex(hsvToRGB([hue.value,s,v])));}
function start(event:PointerEvent){if(props.disabled||event.button!==0)return;dragging=true;square.value!.setPointerCapture(event.pointerId);pick(event);}
function key(event:KeyboardEvent){if(props.disabled||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const values=[...hsv.value],step=event.shiftKey?10:1,index=['ArrowLeft','ArrowRight'].includes(event.key)?1:2;values[index]=Math.max(0,Math.min(100,values[index]+step*(['ArrowLeft','ArrowDown'].includes(event.key)?-1:1)));change(rgbToHex(hsvToRGB(values)));}
function add(){if(props.swatches.length<64&&!props.swatches.includes(active.value))emit('swatches',[...props.swatches,active.value]);}
function remove(){if(selected.value>=0)emit('swatches',props.swatches.filter((_,index)=>index!==selected.value));selected.value=-1;}
watch(hue,draw);onMounted(draw);
</script>
<template><section class="floating-panel palette-panel" @keydown.stop :aria-label="t.palette"><header><strong>{{t.palette}}</strong><button class="icon-button" :aria-label="t.close" @click="emit('close')">×</button></header><div class="button-row"><button :aria-pressed="target==='foreground'" @click="target='foreground'">{{t.foregroundColor}} <span :style="{background:color}"></span></button><button :aria-pressed="target==='background'" @click="target='background'">{{t.backgroundColor}} <span :style="{background}"></span></button></div><div class="sv-square"><canvas ref="square" data-testid="palette-square" width="200" height="140" tabindex="0" role="application" :aria-label="t.saturationValue" @pointerdown="start" @pointermove="dragging&&pick($event)" @pointerup="dragging=false" @pointercancel="dragging=false" @keydown="key"></canvas><i :style="{left:hsv[1]+'%',top:(100-hsv[2])+'%'}"></i></div><label>{{t.hue}}<input type="range" min="0" max="360" :value="hsv[0]" :disabled="disabled" @input="component(0,Number(($event.target as HTMLInputElement).value),'hsv')"></label><label>Hex<input v-model="hex" :disabled="disabled" maxlength="7" data-testid="palette-hex" @change="validHex(hex)?change(hex):hex=active"></label><div class="palette-channels"><label v-for="(name,index) in ['R','G','B']" :key="name">{{name}}<input type="number" min="0" max="255" :value="rgb[index]" :disabled="disabled" @change="component(index,Number(($event.target as HTMLInputElement).value),'rgb')"></label><label v-for="(name,index) in [t.hue,t.saturation,t.brightness]" :key="name">{{name}}<input type="number" min="0" :max="index?100:360" :value="Math.round(hsv[index])" :disabled="disabled" @change="component(index,Number(($event.target as HTMLInputElement).value),'hsv')"></label></div><div class="swatches"><button v-for="(swatch,index) in swatches" :key="index" :aria-label="swatch" :aria-pressed="selected===index" :style="{background:swatch}" :disabled="disabled" @click="selected=index;change(swatch)" @keydown.delete.prevent="selected=index;remove()"></button></div><div class="button-row"><button :disabled="disabled||swatches.length>=64" @click="add()">{{t.addSwatch}}</button><button :disabled="disabled||selected<0" @click="remove()">{{t.remove}}</button></div></section></template>
<style scoped>.palette-panel{width:244px}.palette-panel .button-row{flex-wrap:wrap}.palette-panel span{display:inline-block;width:12px;height:12px;border:1px solid #888}.sv-square{width:100%;aspect-ratio:200/140;position:relative;margin:8px 0}.sv-square canvas{width:100%;height:100%;touch-action:none}.sv-square i{position:absolute;width:8px;height:8px;border:1px solid white;box-shadow:0 0 0 1px black;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.palette-panel>label{display:flex;align-items:center;gap:6px;margin:5px 0}.palette-panel>label input{width:100%;min-width:0}.palette-channels{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.palette-channels input{width:100%;min-width:0}.swatches{display:grid;grid-template-columns:repeat(8,1fr);gap:3px;margin:8px 0}.swatches button{height:22px;min-height:0;padding:0;border:1px solid #777}.swatches button[aria-pressed=true]{outline:2px solid var(--accent);outline-offset:1px}</style>
